    decisionToolPromise ??= decisionRpc('decision_catalogue', 'tools/list', {}).then(result =>
      Array.isArray(result.tools) ? result.tools.filter(tool => tool.name === 'record_decision' && tool.inputSchema?.type === 'object') : [])
