    const head = git(['rev-parse', '--verify', 'HEAD'])
    const remote = git(['remote', 'get-url', 'origin'])
    if (head.status !== 0 || !/^[a-f0-9]{40}$/.test(head.stdout.trim())) throw new Error('repository_head')
